        vector<int>v=colors;
        for(auto it:colors)v.push_back(it);
        int n=v.size();
        vector<int>prefix(n+1,0);
        for(int i=0;i<n;++i)
        {
            if(i-1>=0)
            {
                if(v[i]==v[i-1])
                {
                    prefix[i]++;
                }
            }
            if(i>0)prefix[i]+=prefix[i-1];
            // cout<<prefix[i]<<" ";
        }
        int ans=0;
        int done=0;
        for(int i=0;i<colors.size();++i)
        {
            int l=prefix[i];
            int r=prefix[i+k-1];
            if(r-l==0)++ans;
        }
        return ans;
    }
};

class Solution {
public:
    void build(int i,int l,int r,vector<int>&nums,vector<int>&seg)
    {
        if(l==r)
        {
            seg[i]=nums[l];
            return;
        }
        if(l>r)return;
        int mid=(l+r)>>1;
        build(2*i+1,l,mid,nums,seg);
        build(2*i+2,mid+1,r,nums,seg);
        seg[i]=seg[2*i+1]&seg[2*i+2];
    }
    int query(int i,int low,int high,int l,int r,vector<int>&seg)
    {
        if(low>=l && high<=r)return seg[i];
        if(low>high)return -1;
        if(low>r || high<l)return -1;
        int mid=(l+r)>>1;
        int left=query(2*i+1,low,mid,l,r,seg);
        int right=query(2*i+2,mid+1,high,l,r,seg);
        return left&right;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        vector<int>seg(4*n+1,-1);
        build(0,0,n-1,nums,seg);
