        map<long long,long long>m1;
        for(int i=0;i<n;++i)
        {
            long long tot=nums[i];
            map<long long,long long>temp;
            if(nums[i]==k)
            {
                ++ans;
            }
            temp[nums[i]]=1;
            for(auto it:m1)
            {
